INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 37, 'theory', 'Quiz: programs and environment');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 37, 0, 'Where should error messages normally be sent so that they can be separated from the data?', '["To stdout", "To stderr", "To the file data.txt", "To sys.argv"]', 1, 'print(..., file=sys.stderr): when output is redirected, errors stay on the screen while the data goes to the file.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 37, 1, 'What does argparse do if the user passes an invalid value?', '["Silently ignores it", "Prints an error message and ends the program with code 2", "Replaces it with the default value", "Returns None"]', 1, 'parse_args reports the problem itself and calls sys.exit(2).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 37, 2, 'Which logging level shows only warnings and anything more serious?', '["DEBUG", "INFO", "WARNING", "NOTSET"]', 2, 'The levels are DEBUG < INFO < WARNING < ERROR < CRITICAL; messages below the configured level are not printed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 37, 3, 'Why is the command passed to subprocess.run as a list, without shell=True?', '["It is faster", "User data cannot turn into shell commands", "A list is shorter than a string", "shell=True is forbidden"]', 1, 'shell=True with a string built from someone else''s input is a classic command injection vulnerability.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 37, 4, 'What does the check if __name__ == "__main__" mean?', '["The file is named main", "The code under it runs only when the file is launched as a program, not when it is imported", "The code always runs", "It runs the tests"]', 1, 'When a module is imported, __name__ equals the module name, not "__main__".');
